  exist_val = rp[0];
  rp[0] = ((((exist_val >> 22) << 16) | (addr >> 16)) << 6) | (exist_val & 0x3F);
  exist_val = rp[1];
  rp[1] = ((((exist_val >> 22) << 16) | (addr & 0xFFFF)) << 6) | (exist_val & 0x3F);
  break;

 case 2:
  {
  unsigned int high = (addr >> 16);
  if ((addr >> 15) & 1)
   high = (high + 1) & 0xFFFF;
  exist_val = rp[0];
  rp[0] = ((((exist_val >> 22) << 16) | high) << 6) | (exist_val & 0x3F);
  exist_val = rp[1];
  rp[1] = ((((exist_val >> 22) << 16) | (addr & 0xFFFF)) << 6) | (exist_val & 0x3F);
