  next = current + next_children + 1;
  if (id == next) {
   *parent_id = node;
   *next_max_children = next_children;
   return 1;
  }
  if (id > current && id < next) {
   return search_tree(id, current, next_children, width,
        parent_id, next_max_children,
        depth);
  }
  current = next;
 }
 *parent_id = -1;
 *next_max_children = -1;
 return 0;
}

