{
 unsigned int in_mask, out_mask;
 int byte = 0;
 while ( in_pos < 32 ) {
  in_mask = 1 << ( 31 - in_pos );
  out_mask = 1 << ( 7 - out_pos );
  if ( value & in_mask ) out[byte] |= out_mask;
  in_pos++;
  out_pos++;
  if ( out_pos > 7 ) {
   out_pos=2;
   byte++;
  }
 }
}

